using BetaFit.Desktop.Forms;using BetaFit.Desktop.Helpers;using BetaFit.Desktop.Models;using BetaFit.Desktop.Services;
namespace BetaFit.Desktop.Controls;
public sealed class UcCategories:UserControl {private readonly IBetaFitApiService _api;private readonly TextBox search=new();private readonly DataGridView grid=new();private List<CategoryResponse> items=new();public UcCategories(IBetaFitApiService api){_api=api;Dock=DockStyle.Fill;BackColor=Color.FromArgb(15,18,23);Padding=new Padding(28);var bar=new Panel{Dock=DockStyle.Top,Height=55};search.PlaceholderText="Pesquisar categoria...";search.Width=280;search.Location=new Point(0,12);var go=new Button{Text="Pesquisar",Location=new Point(290,10),Width=100};var add=new Button{Text="Nova categoria",Location=new Point(400,10),Width=120};bar.Controls.AddRange(new Control[]{search,go,add});grid.Dock=DockStyle.Fill;FormHelper.StyleGrid(grid);Controls.Add(grid);Controls.Add(bar);go.Click+=(_,_)=>Render();add.Click+=async(_,_)=>await EditAsync(null);grid.CellDoubleClick+=async(_,e)=>{if(e.RowIndex>=0&&grid.Rows[e.RowIndex].Tag is CategoryResponse c)await EditAsync(c.Id);};Load+=async(_,_)=>await LoadAsync();var menu=new ContextMenuStrip();menu.Items.Add("Editar",null,async(_,_)=>{if(grid.CurrentRow?.Tag is CategoryResponse c)await EditAsync(c.Id);});menu.Items.Add("Ativar",null,async(_,_)=>await ActionAsync(_api.ActivateCategoryAsync));menu.Items.Add("Desativar",null,async(_,_)=>await ActionAsync(_api.DeactivateCategoryAsync));menu.Items.Add("Excluir",null,async(_,_)=>{if(grid.CurrentRow?.Tag is CategoryResponse c&&MessageBox.Show("Excluir esta categoria?","BetaFit",MessageBoxButtons.YesNo)==DialogResult.Yes)try{await _api.DeleteCategoryAsync(c.Id);await LoadAsync();}catch(Exception x){Error(x);}});grid.ContextMenuStrip=menu;}private async Task LoadAsync(){try{items=(await _api.GetCategoriesAsync()).ToList();Render();}catch(Exception ex){Error(ex);}}private void Render(){grid.Rows.Clear();grid.Columns.Clear();foreach(var h in new[]{"Nome","Descrição","Produtos","Status"})grid.Columns.Add(h.ToLower(),h);foreach(var c in items.Where(x=>string.IsNullOrWhiteSpace(search.Text)||x.Name.Contains(search.Text,StringComparison.OrdinalIgnoreCase))){var i=grid.Rows.Add(c.Name,c.Description,c.ProductCount,c.IsActive?"Ativa":"Inativa");grid.Rows[i].Tag=c;}}private async Task EditAsync(Guid? id){using var f=new FrmCategoryForm(_api,id);if(f.ShowDialog(FindForm())==DialogResult.OK)await LoadAsync();}private async Task ActionAsync(Func<Guid,Task> a){if(grid.CurrentRow?.Tag is CategoryResponse c)try{await a(c.Id);await LoadAsync();}catch(Exception x){Error(x);}}private static void Error(Exception e)=>MessageBox.Show(e.Message,"BetaFit",MessageBoxButtons.OK,MessageBoxIcon.Warning);}